    @Test
    void canRunRfgTask() throws IOException {
        writeString(getSettingsFile(), SIMPLE_SETTINGS_FILE);
        writeString(getBuildFile(), SIMPLE_BUILD_FILE);
        writeString(getPropertiesFile(), SIMPLE_PROPERTIES_FILE);
        Files.createDirectories(
            projectDir.toPath()
                .resolve("src/main/java/com/myname/mymodid"));

        // Run the build
        GradleRunner runner = GradleRunner.create()
            .withEnvironment(ImmutableMap.of("VERSION", "1.0.0"))
            .withArguments(
                "--stacktrace",
                "--build-cache",
                "--configuration-cache",
                "--warning-mode",
                "all",
                "downloadVanillaJars");
        runner.forwardOutput();
        runner.withPluginClasspath();
        runner.withProjectDir(projectDir);
        BuildResult result = runner.build();

        // Verify the result
        assertNotEquals(
            result.task(":downloadVanillaJars")
                .getOutcome(),
            TaskOutcome.FAILED);
    }

    private void writeString(File file, String string) throws IOException {
        try (Writer writer = new FileWriter(file)) {
            writer.write(string);
        }
    }

    /** Project setups whose dependencies this test run downloaded, which --offline builds rely on */
    private static final Set<String> CACHED_SETUPS = new HashSet<>();

    private GradleRunner createRunner(String... args) {
        final List<String> arguments = List.of(args);
        if (arguments.contains("--offline") && CACHED_SETUPS.add(readProperties())) {
            // A fresh TestKit home, like on CI, has nothing cached yet
            createOnlineRunner(
                arguments.stream()
                    .filter(argument -> !argument.equals("--offline"))
                    .toList())
                .build();
        }
        return createOnlineRunner(arguments);
    }

    private GradleRunner createOnlineRunner(List<String> args) {
        return GradleRunner.create()
            .withEnvironment(ImmutableMap.of("VERSION", "1.0.0"))
            .withArguments(args)
            .forwardOutput()
            .withPluginClasspath()
            .withProjectDir(projectDir);
    }

    private String readProperties() {
        try {
            return Files.readString(getPropertiesFile().toPath());
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

